<?php require_once __DIR__."/auth.php"; if(empty($_SESSION["user_id"])||($_SESSION["role"]??"")!=="admin"){header("Location: login.php");exit;} $result=$conn->query("SELECT id,username,email,role,status FROM users ORDER BY id DESC"); ?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin Dashboard</title><link rel="stylesheet" href="style.css"></head><body><header><h1>StudentHub Portal</h1><p>Administrator Dashboard</p></header><nav><a href="index.php">Home</a><a href="about.php">About</a><a href="logout.php">Logout</a></nav><main class="wide-card"><h2>Welcome, <?=htmlspecialchars($_SESSION["username"],ENT_QUOTES,"UTF-8")?>!</h2><p>You are logged in as an administrator.</p><h3>Registered Users</h3><div class="table-wrap"><table><thead><tr><th>ID</th><th>Username</th><th>Email</th><th>Role</th><th>Status</th></tr></thead><tbody><?php if($result){while($r=$result->fetch_assoc()){?><tr><td><?=(int)$r["id"]?></td><td><?=htmlspecialchars($r["username"],ENT_QUOTES,"UTF-8")?></td><td><?=htmlspecialchars($r["email"],ENT_QUOTES,"UTF-8")?></td><td><?=htmlspecialchars($r["role"],ENT_QUOTES,"UTF-8")?></td><td><?=htmlspecialchars($r["status"],ENT_QUOTES,"UTF-8")?></td></tr><?php }}?></tbody></table></div></main><footer>© 2026 StudentHub Portal - CHARUSAT</footer></body></html>